#!/usr/bin/env python3
"""Render reviewed content from evidence-map.json; layout and interaction only."""
import json,html
from pathlib import Path
R=Path(__file__).resolve().parents[1]; slides=json.loads((R/'slides/evidence-map.json').read_text()); sources={x['id']:x for x in json.loads((R/'raw/sources.json').read_text())}
blocks=[]
for s in slides:
 links=' · '.join(f'<a href="{html.escape(sources[i]["url"],quote=True)}" target="_blank" rel="noopener">{i}</a>' for i in s['source_ids'])
 wiki='https://github.com/Ava0309/eeg-ei-wiki/blob/main/'+s['wiki_page']
 extra=''
 if s['interaction']=='signal':extra='<div class="interactive"><label for="freq">合成訊號的主要頻率：<output id="freqval">10</output> Hz</label><input id="freq" type="range" min="5" max="20" value="10" step="1"><div class="plotgrid"><canvas id="wave" width="600" height="170" aria-label="合成時域訊號"></canvas><canvas id="psd" width="600" height="170" aria-label="合成訊號的功率頻譜"></canvas></div><small>Synthetic Data · 128 Hz 取樣、1 秒；圖為簡化 periodogram。</small></div>'
 if s['interaction']=='exponent':extra='<div class="interactive"><label for="beta">指數 β：<output id="betaval">1.5</output></label><input id="beta" type="range" min="0" max="3" step="0.1" value="1.5"><canvas id="slope" width="800" height="210" aria-label="模擬冪次頻譜"></canvas><small>Synthetic Data · 雙對數座標；固定 A = 1，非真實 EEG。</small></div>'
 blocks.append(f'<section class="slide" id="slide-{s["id"]}" data-id="{s["id"]}" hidden><div class="eyebrow">EEG / E–I BALANCE <span>{s["id"]} / {len(slides):02}</span></div><h1>{html.escape(s["title"])}</h1><div class="content">{s["body"]}{extra}</div><footer>來源 {links} <span>·</span> <a href="{wiki}" target="_blank" rel="noopener">Wiki 與證據</a><br><small>{html.escape(s["source_locator"])}</small></footer></section>')
css='''*{box-sizing:border-box}body{margin:0;background:#08101d;color:#eaf2fa;font-family:-apple-system,BlinkMacSystemFont,"Noto Sans TC",sans-serif}main{width:min(1100px,94vw);margin:2vh auto}.slide{background:linear-gradient(135deg,#13243a,#0d192a);border:1px solid #29415a;border-radius:20px;padding:clamp(22px,4vw,54px);min-height:84vh;display:flex;flex-direction:column}.slide[hidden]{display:none}.eyebrow{font-size:.75rem;letter-spacing:.18em;color:#74d9cf;font-weight:700;display:flex;justify-content:space-between}h1{font-size:clamp(1.8rem,4vw,3.2rem);line-height:1.15;margin:.6em 0;color:#fff}.content{font-size:clamp(1rem,1.6vw,1.25rem);line-height:1.65;flex:1}.lead{font-size:clamp(1.2rem,2.1vw,1.6rem);color:#d5e8f5}.callout,.interactive,.cards>div,.steps>div,.compare p{background:#192e43;border:1px solid #34536a;border-radius:12px;padding:14px 18px;margin:12px 0}.callout{border-left:4px solid #75ded2}.steps,.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.cards{grid-template-columns:repeat(2,1fr)}.steps b{display:block;color:#7ce1d4}.steps small{display:block;color:#b4c6d5}.formula{font-size:1.5em;color:#86e3d8;margin:.5em 0}.plotgrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}canvas{width:100%;height:auto;background:#0a1624;border-radius:8px;display:block}input{width:min(100%,420px);accent-color:#6fdacb;display:block;margin:10px 0}footer{border-top:1px solid #34485d;padding-top:12px;margin-top:20px;font-size:.82rem;color:#a8bdce}a{color:#82e2d5}nav{display:flex;gap:15px;align-items:center;justify-content:center;padding:14px}button{border:1px solid #45657a;border-radius:8px;background:#1a3046;color:white;padding:10px 18px;font-size:1rem;cursor:pointer}button:disabled{opacity:.4}#progress{width:160px;accent-color:#70dccc}@media(max-width:650px){main{width:100%;margin:0}.slide{min-height:calc(100vh - 72px);border-radius:0;padding:24px}.steps,.cards,.plotgrid{grid-template-columns:1fr}.content{line-height:1.55}.compare p{margin:7px 0;padding:9px}nav{position:sticky;bottom:0;background:#08101d}#progress{width:80px}}'''
js='''const slides=[...document.querySelectorAll('.slide')];let current=0;const count=document.getElementById('count'),progress=document.getElementById('progress');function show(n){current=Math.min(slides.length-1,Math.max(0,n));slides.forEach((s,i)=>s.hidden=i!==current);count.textContent=(current+1)+' / '+slides.length;progress.value=current+1;document.getElementById('prev').disabled=current===0;document.getElementById('next').disabled=current===slides.length-1;window.scrollTo(0,0);drawAll()}document.getElementById('prev').onclick=()=>show(current-1);document.getElementById('next').onclick=()=>show(current+1);document.addEventListener('keydown',e=>{if(e.target.matches('input'))return;if(e.key==='ArrowRight')show(current+1);if(e.key==='ArrowLeft')show(current-1)});function graph(id,values,color,label,bounds=null){let c=document.getElementById(id),x=c.getContext('2d'),w=c.width,h=c.height;x.clearRect(0,0,w,h);x.fillStyle='#0a1624';x.fillRect(0,0,w,h);x.strokeStyle='#405b70';x.beginPath();x.moveTo(45,14);x.lineTo(45,h-27);x.lineTo(w-12,h-27);x.stroke();x.fillStyle='#c2d9e8';x.font='16px sans-serif';x.fillText(label,52,20);let max=bounds?bounds[1]:Math.max(...values),min=bounds?bounds[0]:Math.min(...values),span=max-min||1;x.beginPath();values.forEach((v,i)=>{let px=46+i*(w-60)/(values.length-1),py=h-28-(v-min)/span*(h-65);i?x.lineTo(px,py):x.moveTo(px,py)});x.strokeStyle=color;x.lineWidth=3;x.stroke();}function drawAll(){let f=+document.getElementById('freq').value;document.getElementById('freqval').textContent=f;let n=128,signal=Array.from({length:n},(_,i)=>Math.sin(2*Math.PI*f*i/n)+.35*Math.sin(2*Math.PI*3*i/n));let power=Array.from({length:33},(_,k)=>{let re=0,im=0;signal.forEach((v,i)=>{re+=v*Math.cos(2*Math.PI*k*i/n);im-=v*Math.sin(2*Math.PI*k*i/n)});return(re*re+im*im)/(n*n)});graph('wave',signal,'#79e2d4','時間（1 秒）');graph('psd',power,'#f6bb75','頻率（0–32 Hz）');let b=+document.getElementById('beta').value;document.getElementById('betaval').textContent=b.toFixed(1);let values=Array.from({length:100},(_,i)=>-b*(i/99)*Math.log10(40));graph('slope',values,'#79e2d4','log₁₀ 功率 vs log₁₀ 頻率',[-3*Math.log10(40),0]);}document.getElementById('freq').oninput=drawAll;document.getElementById('beta').oninput=drawAll;show(0);'''
page='<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EEG → E/I 教學</title><style>'+css+'</style></head><body><main>'+''.join(blocks)+'</main><nav aria-label="投影片導覽"><button id="prev">← 上一頁</button><span id="count"></span><progress id="progress" max="'+str(len(slides))+'" value="1"></progress><button id="next">下一頁 →</button></nav><script>'+js+'</script></body></html>'
(R/'index.html').write_text(page)
print('Rendered',len(slides),'slides to index.html')
